// Route builders for the capture / course / item screens. Typed routes are generated by the dev
// server and may not know screens other agents add in parallel, so paths are built here once.
import type { Href } from 'expo-router';

const path = (value: string) => value as Href;
const query = (params: Record<string, string | null | undefined>): string => {
  const parts = Object.entries(params)
    .filter((entry): entry is [string, string] => typeof entry[1] === 'string' && entry[1].length > 0)
    .map(([key, value]) => `${key}=${encodeURIComponent(value)}`);
  return parts.length > 0 ? `?${parts.join('&')}` : '';
};

export const routes = {
  course: (id: string) => path(`/course/${encodeURIComponent(id)}`),
  courseEdit: (id?: string | null) => path(`/course/edit${query({ id })}`),
  item: (id: string) => path(`/item/${encodeURIComponent(id)}`),
  itemNew: (courseId?: string | null) => path(`/item/new${query({ courseId })}`),
  textbook: (id: string) => path(`/textbook/${encodeURIComponent(id)}`),
  upload: (options: { kind?: 'syllabus' | 'toc'; courseId?: string | null; textbookId?: string | null } = {}) =>
    path(`/upload${query({ kind: options.kind, courseId: options.courseId, textbookId: options.textbookId })}`),
  review: (uploadId: string, textbookId?: string | null) => path(`/review/${encodeURIComponent(uploadId)}${query({ textbookId })}`),
  canvas: () => path('/integrations/canvas'),
  discrepancies: () => path('/discrepancies'),
  grades: (courseId: string) => path(`/grades/${encodeURIComponent(courseId)}`),
  focus: (blockKey: string) => path(`/focus${query({ blockKey })}`),
} as const;

/** First value of a route param (expo-router hands back string | string[]). */
export function param(value: string | string[] | undefined): string | null {
  const first = Array.isArray(value) ? value[0] : value;
  return first && first.length > 0 ? first : null;
}
